// @name Sliding puzzle
// @background #efece4
// @refresh 3600
// The 15 puzzle for a touch screen: tap a tile in the gap's row or column to
// slide it (and every tile between) into the gap, and put them back in
// order. 3x3, 4x4 or 5x5, with numbers or a picture cut into tiles. Every
// shuffle can be solved. The puzzle in progress and the best scores are kept.
import { shuffle, slide, isSolved } from './logic'
import { PICTURES, PictureDefs } from './pictures'
import { highContrast, canvasOf, Button, OptionsPage, Title } from './ui'

const THEMES = {
  color: {
    page: 'bg-[#efece4] text-[#22303a]',
    muted: 'text-[#5f6a72]',
    button: 'bg-[#dfd9cb] text-[#22303a] active:bg-[#d0c8b6]',
    primary: 'bg-[#2d3e4a] text-white active:bg-[#3d5262]',
    on: 'bg-[#2d3e4a] text-white',
    off: 'bg-[#dfd9cb] text-[#22303a]',
    board: '#2d3e4a',
    tile: '#f7f1e5',
    tileEdge: '#d9cfbb',
    number: '#2d3e4a',
    home: '#2a7f80',
    badge: '#2d3e4a',
    badgeText: '#ffffff',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    on: 'bg-black text-white',
    off: 'bg-white text-black border-2 border-black',
    board: '#000000',
    tile: '#ffffff',
    tileEdge: '#000000',
    number: '#000000',
    home: '#000000',
    badge: '#000000',
    badgeText: '#ffffff',
  },
}

const settingsOf = (app) => {
  const n = Number(app.state.size)
  return {
    n: n === 3 || n === 5 ? n : 4,
    look: app.state.look === 'landscape' || app.state.look === 'rings' ? app.state.look : 'numbers',
  }
}

// The puzzle in progress, kept in the scene's private `game` field: the
// tiles row by row (0 the gap) and the tiles moved so far.
type Game = { n: number; tiles: number[]; moves: number; done?: boolean }
const loadGame = (app): Game | null => {
  const g = app.state.game
  return g && Array.isArray(g.tiles) && g.tiles.length === g.n * g.n ? g : null
}
const save = (game: Game) => frameos.setState('game', game)
const newGame = (n: number): Game => ({ n, tiles: shuffle(n, Math.random), moves: 0 })

const tapTile = (app, index: number) => {
  const game = loadGame(app)
  if (!game || game.done) return
  const tiles = game.tiles.slice()
  const moved = slide(tiles, game.n, index)
  if (!moved) return
  const next: Game = { n: game.n, tiles, moves: game.moves + moved }
  if (isSolved(tiles)) {
    next.done = true
    const best = app.state.best && typeof app.state.best === 'object' ? { ...app.state.best } : {}
    const key = String(game.n)
    frameos.remember('record', !best[key] || next.moves < best[key])
    if (!best[key] || next.moves < best[key]) {
      best[key] = next.moves
      frameos.setState('best', best)
    }
  }
  save(next)
}

const restart = (app) => {
  save(newGame(settingsOf(app).n))
  frameos.remember('page', null)
}

// Arrow keys slide the tile next to the gap that way; on frames with
// buttons, forward deals a new puzzle once this one is solved.
export function onEvent(app, context) {
  const event = context.event
  const game = loadGame(app)
  if (!game) return false
  if (event === 'forward') {
    if (!game.done) return false
    restart(app)
    return true
  }
  if (event !== 'keyDown') return false
  const p = context.payload || {}
  if (p.ctrl || p.alt || p.meta) return false
  const n = game.n
  const gap = game.tiles.indexOf(0)
  const gr = Math.floor(gap / n)
  const gc = gap % n
  // The tile that moves is on the far side of the gap from the arrow.
  const from = { ArrowLeft: [gr, gc + 1], ArrowRight: [gr, gc - 1], ArrowUp: [gr + 1, gc], ArrowDown: [gr - 1, gc] }[p.key]
  if (from) {
    const [r, c] = from
    if (r >= 0 && r < n && c >= 0 && c < n) tapTile(app, r * n + c)
    return true
  }
  if (String(p.key).toLowerCase() === 'n') {
    restart(app)
    return true
  }
  return false
}

// The board, 1000 units across, each tile a window onto its square of the
// picture or a number.
const Board = ({ t, game, look, high, size }) => {
  const n = game.n
  const cell = 1000 / n
  const pad = cell * 0.04
  const picture = look === 'numbers' ? null : PICTURES[look](high)
  const parts = []
  for (let i = 0; i < game.tiles.length; i++) {
    let tile = game.tiles[i]
    // A solved picture is shown whole, the gap filled.
    if (!tile && game.done && picture) tile = n * n
    if (!tile) continue
    const x = (i % n) * cell + pad
    const y = Math.floor(i / n) * cell + pad
    const w = cell - pad * 2
    const home = tile - 1
    if (picture) {
      const hx = (home % n) * cell + pad
      const hy = Math.floor(home / n) * cell + pad
      parts.push(
        <svg x={x} y={y} width={w} height={w} viewBox={`${hx} ${hy} ${w} ${w}`}>{picture}</svg>,
      )
      if (!game.done) {
        const r = cell * 0.14
        parts.push(<rect x={x + 2} y={y + 2} width={r * 2} height={r * 2} rx={r * 0.5} fill={t.badge} />)
        parts.push(
          <text x={x + 2 + r} y={y + 2 + r * 1.42} fontSize={r * 1.15} fontWeight="bold" textAnchor="middle" fill={t.badgeText}>
            {String(tile)}
          </text>,
        )
      }
    } else {
      const atHome = home === i
      parts.push(<rect x={x} y={y} width={w} height={w} rx={cell * 0.1} fill={t.tile} stroke={t.tileEdge} strokeWidth={high ? 8 : 4} />)
      parts.push(
        <text x={x + w / 2} y={y + w / 2 + cell * 0.15} fontSize={cell * 0.42} fontWeight="bold" textAnchor="middle" fill={atHome ? t.home : t.number}>
          {String(tile)}
        </text>,
      )
    }
  }
  return (
    <svg viewBox="-12 -12 1024 1024" width={size} height={size}>
      {picture && !high ? <PictureDefs /> : null}
      <rect x={-10} y={-10} width={1020} height={1020} rx={24} fill={t.board} />
      {parts}
    </svg>
  )
}

export function get(app, context) {
  const ui = canvasOf(app, context)
  const high = highContrast(app)
  const t = high ? THEMES.high : THEMES.color
  const settings = settingsOf(app)

  if (frameos.recall('page') === 'options') {
    const rows = [
      { field: 'size', label: 'Size', value: String(settings.n), options: [['3', '3 × 3'], ['4', '4 × 4'], ['5', '5 × 5']] },
      { field: 'look', label: 'Tiles', value: settings.look, options: [['numbers', 'Numbers'], ['landscape', 'Landscape'], ['rings', 'Rings']] },
    ]
    return <OptionsPage ui={ui} t={t} title="Sliding puzzle" rows={rows}
      onClose={() => frameos.remember('page', null)} onNew={() => restart(app)} />
  }

  let game = loadGame(app)
  if (!game || game.n !== settings.n) {
    game = newGame(settings.n)
    save(game)
  }
  const n = game.n

  // Side by side or stacked, whichever gives the bigger board.
  const sideW = Math.round(Math.max(ui.W * 0.27, ui.text * 9))
  const sideSize = Math.min(ui.W - sideW - ui.pad * 3, ui.H - ui.pad * 2)
  const stackSize = Math.min(ui.W - ui.pad * 2, ui.H - ui.pad * 2 - ui.gap * 2 - ui.button * 2)
  const side = sideSize >= stackSize
  const size = Math.floor(side ? sideSize : stackSize)
  const board = (
    <div className={`w-[${size}px] h-[${size}px] shrink-0`}
      onClick={(e) => {
        const col = Math.floor(((e.localX / e.width) * 1024 - 12) / (1000 / n))
        const row = Math.floor(((e.localY / e.height) * 1024 - 12) / (1000 / n))
        if (col >= 0 && col < n && row >= 0 && row < n) tapTile(app, row * n + col)
      }}>
      <Board t={t} game={game} look={settings.look} high={high} size={size} />
    </div>
  )

  const best = app.state.best && typeof app.state.best === 'object' ? app.state.best[String(n)] : 0
  const headline = game.done ? 'Solved!' : `${game.moves} ${game.moves === 1 ? 'move' : 'moves'}`
  const detail = game.done
    ? `In ${game.moves} moves${frameos.recall('record') ? ', a new best' : best ? `. Best: ${best}` : ''}`
    : best ? `Best for ${n} × ${n}: ${best}` : `${n} × ${n}: put the tiles in order`
  const status = (
    <div className="flex flex-col">
      <span className={`text-[${ui.big}px] font-bold leading-tight`}>{headline}</span>
      <span className={`text-[${ui.small}px] ${t.muted}`}>{detail}</span>
    </div>
  )
  const buttons = [
    <Button ui={ui} grow={!side} className={game.done ? t.primary : t.button} onClick={() => restart(app)}>New puzzle</Button>,
    <Button ui={ui} grow={!side} className={t.button} onClick={() => frameos.remember('page', 'options')}>Options</Button>,
  ]

  if (side) {
    return (
      <div className={`flex w-full h-full p-[${ui.pad}px] gap-[${ui.pad}px] items-center ${t.page}`}>
        {board}
        <div className={`flex-1 h-full flex flex-col gap-[${ui.gap}px]`}>
          <Title ui={ui} width={ui.W - ui.pad * 3 - size}>Sliding puzzle</Title>
          {status}
          <div className="flex-1" />
          <div className={`space-y-[${ui.gap}px]`}>{buttons}</div>
        </div>
      </div>
    )
  }
  return (
    <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${ui.gap}px] items-center ${t.page}`}>
      {ui.H > ui.W * 1.3 ? <span className={`w-full text-[${ui.title}px] font-bold leading-tight`}>Sliding puzzle</span> : null}
      <div className={`flex items-center w-full h-[${ui.button}px]`}>{status}</div>
      <div className="flex-1 flex items-center justify-center">{board}</div>
      <div className={`flex w-full gap-[${ui.gap}px]`}>{buttons}</div>
    </div>
  )
}

